#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<string> g(n);
    for (int i = 0; i < n; i++) {
        cin >> g[i];
    }

    vector<int> heights(m, 0);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) heights[j] = g[i][j] == '1' ? heights[j] + 1 : 0;
        vector<int> stack;
        vector<long long> cnt(m, 0);
        for (int j = 0; j < m; j++) {
            while (!stack.empty() && heights[stack.back()] >= heights[j]) stack.pop_back();
            if (!stack.empty()) {
                int p = stack.back();
                cnt[j] = cnt[p] + (long long) heights[j] * (j - p);
            } else {
                cnt[j] = (long long) heights[j] * (j + 1);
            }
            stack.push_back(j);
            total += cnt[j];
        }
    }
    cout << total << "\n";

    return 0;
}

